+    private const float OpaqueMaterialThreshold = .96f;
     private sealed record Primitive(Vector2[] Polygon, Vector2[] Uv, Color Tint, bool NativeAlpha,
         Vector2 A, Vector2 B, Vector2 C, Vector2 Ua, Vector2 Ub, Vector2 Uc)
     {
